```

back:
// Why: A destructuring default applies when the property is missing or undefined (not for
// null or "").
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Destructuring
function formatUser(user) {
  const { firstName, lastName, role = "GUEST" } = user;
  return `${lastName}, ${firstName} (${role.toUpperCase()})`;
}

