back:
// Why: `key in obj` asks whether the property exists. Testing its value instead drops real
// properties that hold null, 0 or "", and copying blindly adds undefined keys.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/in
function pick(obj, keys) {
  const result = {};
  for (const key of keys) {
    if (key in obj) result[key] = obj[key];
  }
  return result;
}

